package com.spaceagent.platform.integration.infrastructure.http;
import com.spaceagent.platform.automation.api.AutomationTriggerApplicationApi;import com.spaceagent.shared.auth.TenantAuthenticationDetails;import com.spaceagent.shared.exception.GlobalExceptionHandler;import java.time.Instant;import java.util.List;import org.junit.jupiter.api.Test;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class PlatformAutomationTriggerHttpControllerTest{@Test void tenantHttpCreatesTypedTriggerAndFencesLifecycle()throws Exception{var api=mock(AutomationTriggerApplicationApi.class);var view=new AutomationTriggerApplicationApi.TriggerView("id","lineage",1,null,"agent","follow","continue","FOLLOW_UP","sha256:"+"a".repeat(64),"DRAFT",1,Instant.EPOCH,null,null);when(api.create(any())).thenReturn(view);when(api.activate(any())).thenReturn(new AutomationTriggerApplicationApi.TriggerView("id","lineage",1,null,"agent","follow","continue","FOLLOW_UP","sha256:"+"a".repeat(64),"ACTIVE",2,Instant.EPOCH,Instant.EPOCH,null));var mvc=MockMvcBuilders.standaloneSetup(new PlatformAutomationTriggerHttpController(api)).setControllerAdvice(new GlobalExceptionHandler()).build();var auth=new UsernamePasswordAuthenticationToken("owner",null,List.of());auth.setDetails(new TenantAuthenticationDetails("tenant","MEMBER"));mvc.perform(post("/api/v1/automation-triggers").principal(auth).header("Idempotency-Key","request-001").contentType("application/json").content("{\"agentId\":\"agent\",\"description\":\"follow\",\"prompt\":\"continue\",\"type\":\"FOLLOW_UP\",\"conversationId\":\"conversation\",\"sourceTaskId\":\"task\",\"delaySeconds\":600}")).andExpect(status().isCreated()).andExpect(jsonPath("$.data.state").value("DRAFT"));verify(api).create(argThat(c->c.tenantId().equals("tenant")&&c.ownerUserId().equals("owner")&&c.source() instanceof com.spaceagent.platform.automation.domain.AutomationTriggerSource.FollowUp));mvc.perform(post("/api/v1/automation-triggers/id/activate").principal(auth).param("expectedRevision","1")).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("ACTIVE"));verify(api).activate(argThat(c->c.expectedRevision()==1));}}
